PREFIX soc: <https://w3id.org/socratico/def/core#>
PREFIX schema: <http://schema.org/>

# Las contrataciones del grafo son los pares mayores (12 proveedores por
# institución, 8 clientes por empresa): la suma es un piso, no el total.
SELECT ?empresa ?nombre ?medidas ?contratado
WHERE {
  { SELECT ?proveedor (COUNT(?medida) AS ?medidas)
    WHERE { ?proveedor soc:tieneMedida ?medida } GROUP BY ?proveedor }
  { SELECT ?proveedor (SUM(?monto) AS ?contratado)
    WHERE { ?c a soc:Contratacion ; soc:contratista ?proveedor ; soc:montoContratado ?monto }
    GROUP BY ?proveedor }
  ?empresa soc:inscritaComo ?proveedor ;
           schema:legalName ?nombre .
}
ORDER BY DESC(?contratado) ?nombre
LIMIT 10

PREFIX soc: <https://w3id.org/socratico/def/core#>
PREFIX schema: <http://schema.org/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?proveedor ?nombre ?contratos ?monto
WHERE {
  ?minerd a soc:Institucion ; skos:altLabel "MINERD" .
  ?c a soc:Contratacion ;
     soc:contratante ?minerd ;
     soc:contratista ?proveedor ;
     soc:numeroDeContratos ?contratos ;
     soc:montoContratado ?monto .
  ?proveedor rdfs:label ?nombre .
}
ORDER BY DESC(?monto) ?nombre
LIMIT 12

PREFIX soc: <https://w3id.org/socratico/def/core#>
PREFIX schema: <http://schema.org/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?obra ?nombre ?valor ?avance ?ejecutora
WHERE {
  ?obra a soc:ProyectoDeInversion ;
        rdfs:label ?nombre ;
        soc:valorEstimado ?valor ;
        soc:avance ?avance .
  OPTIONAL { ?obra soc:ejecutadoPor ?i . ?i schema:name ?ejecutora }
}
ORDER BY DESC(?valor) ?nombre
LIMIT 10

PREFIX soc: <https://w3id.org/socratico/def/core#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

# La modalidad de cada proceso es un concepto del vocabulario do:modalidades;
# su nombre en llano está en el grafo de la ontología. Un proceso sin valor
# estimado cuenta como proceso y suma cero.
SELECT ?modalidad ?nombre (COUNT(?proceso) AS ?procesos) (SUM(COALESCE(?valor, 0)) AS ?valorEstimado)
WHERE {
  ?proceso a soc:ProcesoDeContratacion ;
           soc:modalidad ?modalidad .
  OPTIONAL { ?proceso soc:valorEstimado ?valor }
  ?modalidad skos:prefLabel ?nombre .
}
GROUP BY ?modalidad ?nombre
ORDER BY DESC(?procesos) ?nombre

PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dct: <http://purl.org/dc/terms/>

# Cada triple está en el grafo con nombre de su fuente y su corte, o de la
# regla de Socrático.do que lo deriva; el PROV-O de cada grafo dice cuál.
SELECT ?fuente ?corte ?relacion (COUNT(*) AS ?triples)
WHERE {
  ?minerd skos:altLabel "MINERD" .
  GRAPH ?grafo { { ?minerd ?relacion ?o } UNION { ?o ?relacion ?minerd } }
  OPTIONAL { ?grafo rdfs:label ?fuente ; dct:date ?corte }
}
GROUP BY ?fuente ?corte ?relacion
ORDER BY DESC(?triples) ?relacion

PREFIX soc: <https://w3id.org/socratico/def/core#>
PREFIX schema: <http://schema.org/>

# Un contrato puede servir a varias obras: su monto se suma una vez por contrato.
SELECT ?empresa ?nombre (COUNT(?contrato) AS ?contratos) (SUM(?monto) AS ?contratado) (SUM(?obras) AS ?enObras)
WHERE {
  { SELECT ?contrato ?proveedor ?monto (COUNT(?obra) AS ?obras)
    WHERE { ?contrato a soc:Contrato ; soc:contratista ?proveedor ; soc:monto ?monto ; soc:paraProyecto ?obra }
    GROUP BY ?contrato ?proveedor ?monto }
  ?empresa soc:inscritaComo ?proveedor ;
           schema:legalName ?nombre .
}
GROUP BY ?empresa ?nombre
ORDER BY DESC(?contratado) ?nombre
LIMIT 10

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?clase ?nombre ?nodos
WHERE {
  GRAPH <https://w3id.org/socratico/def/core> {
    ?clase a owl:Class ; rdfs:label ?nombre .
    FILTER(LANG(?nombre) = "es")
  }
  { SELECT ?clase (COUNT(?s) AS ?nodos) WHERE { ?s a ?clase } GROUP BY ?clase }
}
ORDER BY DESC(?nodos) ?nombre

PREFIX sh: <http://www.w3.org/ns/shacl#>
PREFIX soc: <https://w3id.org/socratico/def/core#>

SELECT ?propiedad ?minimo ?maximo ?tipo ?clase
WHERE {
  GRAPH <https://w3id.org/socratico/def/formas> {
    ?forma sh:targetClass soc:Empresa ;
           sh:property ?p .
    ?p sh:path ?propiedad .
    OPTIONAL { ?p sh:minCount ?minimo }
    OPTIONAL { ?p sh:maxCount ?maximo }
    OPTIONAL { ?p sh:datatype ?tipo }
    OPTIONAL { ?p sh:class ?clase }
  }
}
ORDER BY ?propiedad

PREFIX soc: <https://w3id.org/socratico/def/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <http://schema.org/>

CONSTRUCT {
  ?obra rdfs:label ?nombre ; soc:ejecutadoPor ?ejecutora ; soc:enProvincia ?provincia .
  ?ejecutora schema:name ?nombreEjecutora .
  ?proceso soc:paraProyecto ?obra ; rdfs:label ?titulo .
  ?contrato soc:paraProyecto ?obra ; soc:contratista ?contratista ; soc:monto ?monto .
  ?contratista rdfs:label ?nombreContratista .
}
WHERE {
  { SELECT ?obra (COUNT(?c) AS ?n) WHERE { ?c a soc:Contrato ; soc:paraProyecto ?obra } GROUP BY ?obra ORDER BY DESC(?n) ?obra LIMIT 1 }
  ?obra rdfs:label ?nombre .
  OPTIONAL { ?obra soc:ejecutadoPor ?ejecutora . ?ejecutora schema:name ?nombreEjecutora }
  OPTIONAL { ?obra soc:enProvincia ?provincia }
  OPTIONAL { ?proceso a soc:ProcesoDeContratacion ; soc:paraProyecto ?obra ; rdfs:label ?titulo }
  OPTIONAL { ?contrato a soc:Contrato ; soc:paraProyecto ?obra ; soc:contratista ?contratista ; soc:monto ?monto .
             OPTIONAL { ?contratista rdfs:label ?nombreContratista } }
}
